#include <SPI.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <U8g2_for_Adafruit_GFX.h>
#include <RTClib.h>

// --- Пины ST7789 ---
#define TFT_CS   10
#define TFT_DC    8
#define TFT_RST   9
#define TFT_BLK   7

// --- Цвета ---
#define TOYOTA_RED 0xE805   // RGB565 ~ (235, 0, 41)

// --- Объекты ---
Adafruit_ST7789 tft = Adafruit_ST7789(TFT_CS, TFT_DC, TFT_RST);
U8G2_FOR_ADAFRUIT_GFX u8g2;
RTC_DS3231 rtc;

const int W = 240;
const int H = 320;
int lastMinute = -1;

// ---------- Рисуем эмблему Toyota ----------
void drawEllipseThick(int cx, int cy, int rw, int rh, int thick, uint16_t color) {
  for (int i = 0; i < thick; i++) {
    tft.drawEllipse(cx, cy, rw - i, rh - i, color);
  }
}

void drawToyotaLogo(int cx, int cy, int rw) {
  int rh = rw * 2 / 3;
  drawEllipseThick(cx, cy, rw, rh, 5, TOYOTA_RED);
  drawEllipseThick(cx, cy, rw / 3, rh - 8, 4, TOYOTA_RED);
  drawEllipseThick(cx, cy - rh / 3, rw - 22, rh / 4, 4, TOYOTA_RED);
}

// ---------- Экраны ----------
void showSplashLogo() {
  tft.fillScreen(ST77XX_BLACK);
  drawToyotaLogo(W / 2, H / 2, 95);
}

void showSlogan() {
  tft.fillScreen(ST77XX_BLACK);
  u8g2.setFont(u8g2_font_helvB18_t_cyrillic);
  u8g2.setForegroundColor(ST77XX_WHITE);

  const char* line1 = "УПРАВЛЯЙ";
  const char* line2 = "МЕЧТОЙ";
  int w1 = u8g2.getUTF8Width(line1);
  int w2 = u8g2.getUTF8Width(line2);

  u8g2.setCursor((W - w1) / 2, H / 2 - 5);
  u8g2.print(line1);
  u8g2.setCursor((W - w2) / 2, H / 2 + 30);
  u8g2.print(line2);
}

void showClock() {
  DateTime now = rtc.now();
  char timeBuf[6];
  char dateBuf[11];
  sprintf(timeBuf, "%02d:%02d", now.hour(), now.minute());
  sprintf(dateBuf, "%02d.%02d.%04d", now.day(), now.month(), now.year());

  tft.fillScreen(ST77XX_BLACK);

  u8g2.setFont(u8g2_font_fub30_tn);
  u8g2.setForegroundColor(ST77XX_WHITE);
  int w = u8g2.getUTF8Width(timeBuf);
  u8g2.setCursor((W - w) / 2, H / 2);
  u8g2.print(timeBuf);

  u8g2.setFont(u8g2_font_helvB14_t_cyrillic);
  u8g2.setForegroundColor(ST77XX_CYAN);
  w = u8g2.getUTF8Width(dateBuf);
  u8g2.setCursor((W - w) / 2, H / 2 + 55);
  u8g2.print(dateBuf);
}

// ---------- Setup ----------
void setup() {
  Serial.begin(9600);

  pinMode(TFT_BLK, OUTPUT);
  digitalWrite(TFT_BLK, HIGH);

  tft.init(240, 320);
  tft.setRotation(0);
  tft.fillScreen(ST77XX_BLACK);

  u8g2.begin(tft);
  u8g2.setFontMode(1);

  Wire.begin();
  if (!rtc.begin()) {
    Serial.println(F("DS3231 не найден!"));
  }
  if (rtc.lostPower()) {
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  showSplashLogo();
  delay(5000);

  showSlogan();
  delay(3000);

  showClock();
  lastMinute = rtc.now().minute();
}

// ---------- Loop ----------
void loop() {
  DateTime now = rtc.now();
  if (now.minute() != lastMinute) {
    lastMinute = now.minute();
    showClock();
  }
  delay(200);
}
